class Solution:
    def __init__(self):
        self.max = float('-inf')

    def maxPathSum(self, root: TreeNode) -> int:
        self.find(root)
        return self.max

    def find(self, root: TreeNode) -> int:
        if root is None:
            return 0
        l = self.find(root.left)
        r = self.find(root.right)
        s = l + r + root.val
        if s > self.max:
            self.max = s
        temp = l if l > r else r
        return temp + root.val if temp + root.val > 0 else 0
